package com.shipsense.repository;

import com.shipsense.entity.Hub;
import org.springframework.data.jpa.repository.JpaRepository;

import java.util.Optional;

/**
 * Spring Data JPA repository for {@link Hub}.
 * The CRUD methods (findAll, findById, save, ...) are generated by Spring Data;
 * we only declare the extra finders we need.
 */
public interface HubRepository extends JpaRepository<Hub, Integer> {

    Optional<Hub> findByCode(String code);

    boolean existsByCode(String code);
}
